import ForceGraph3D from '3d-force-graph';
import { useEffect, useRef } from 'react';

export default function Graph3D() {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    fetch('http://localhost:5001/rag/graph')
      .then(res => res.json())
      .then(data => {
        // Cast to any to bypass strict TS constructor/callable mismatch
        const ForceGraph: any = ForceGraph3D;
        const myGraph = ForceGraph()(ref.current!);
        myGraph.graphData(data);
      });
  }, []);
  return <div ref={ref} style={{ width: '100%', height: '600px' }} />;
}
