import { useEffect, useRef } from 'react';
import Chart from 'chart.js/auto';
import Prism from 'prismjs';
import 'prismjs/themes/prism-tomorrow.css';

export default function InsightsPanel() {
  const chartRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    // Fetch timeline data from local backend (falls back to empty if offline)
    fetch('http://localhost:5001/rag/timeline')
      .then(res => res.json())
      .then(data => {
        if (data.timeline && chartRef.current) {
          new Chart(chartRef.current, {
            type: 'line',
            data: {
              labels: data.timeline.map((d: any) => d.date),
              datasets: [
                { label: 'Errors', data: data.timeline.map((d: any) => d.errors), borderColor: 'red' },
                { label: 'Commands', data: data.timeline.map((d: any) => d.commands), borderColor: 'blue' }
              ]
            }
          });
        }
      });

    // Initialize syntax highlighting for all code blocks
    Prism.highlightAll();
  }, []);

  return (
    <div>
      <h2>Timeline Insights</h2>
      <canvas ref={chartRef} style={{ maxHeight: '300px' }} />
      <h2>Working Code (Highlighted)</h2>
      {/* This will be populated by the search results */}
    </div>
  );
}
